"""Reminders.

* Standard reminder: each participant gets an "upcoming event" reminder
  ``reminder_lead_hours`` (default 24h) before the event, scheduled when they RSVP.
* Smart reminders (beta), generated by the scheduler from event proximity and task progress:
    - participants holding unfinished tasks: at 24h and 3h before the event (task_reminder)
    - unclaimed tasks: participants are nudged at 24h and 6h, marked urgent when less
      than half of the tasks are done (smart_reminder)
    - minimum participants not reached: group members who have not RSVP'd are nudged at
      48h and 12h (smart_reminder)

Every reminder row has a ``dedupe_key`` (unique), so re-running the generator is safe.
"""
from datetime import datetime, timedelta

from sqlalchemy import delete, func, select, update
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session

from app.db import utcnow
from app.models import (
    RSVP,
    Event,
    EventGroup,
    EventStatus,
    GroupMembership,
    NotificationKind,
    Reminder,
    Task,
    TaskAssignment,
    TaskStatus,
)
from app.services.delivery import actor_key
from app.services.notifications import get_preferences, notify


def _add(db: Session, **values) -> bool:
    """Insert a reminder unless one with the same dedupe_key exists."""
    if db.scalar(select(Reminder.id).where(Reminder.dedupe_key == values["dedupe_key"])):
        return False
    try:
        with db.begin_nested():
            db.add(Reminder(**values))
        return True
    except IntegrityError:
        return False


def schedule_event_reminder(db: Session, event: Event, user_id: str | None, guest_id: str | None) -> None:
    lead = get_preferences(db, user_id, guest_id).reminder_lead_hours
    due = event.starts_at - timedelta(hours=lead)
    if due <= utcnow():
        return
    _add(
        db,
        event_id=event.id,
        user_id=user_id,
        guest_id=guest_id,
        kind=NotificationKind.EVENT_REMINDER,
        dedupe_key=f"event_reminder:{event.id}:{actor_key(user_id, guest_id)}:{int(event.starts_at.timestamp())}",
        due_at=due,
        title=f"Coming up: {event.name}",
        body=f"Starts {event.starts_at:%a %d %b, %H:%M} UTC",
    )


def reschedule_event_reminders(db: Session, event: Event) -> None:
    """After a time change: drop unsent standard reminders and schedule new ones."""
    db.execute(delete(Reminder).where(Reminder.event_id == event.id, Reminder.sent_at.is_(None), Reminder.kind == NotificationKind.EVENT_REMINDER))
    for user_id, guest_id in db.execute(select(RSVP.user_id, RSVP.guest_id).where(RSVP.event_id == event.id)).all():
        schedule_event_reminder(db, event, user_id, guest_id)


def _bucket(hours_left: float, thresholds: list[int]) -> int | None:
    """Smallest threshold that the event is within, e.g. 20h left with [24, 3] -> 24."""
    hit = [t for t in thresholds if hours_left <= t]
    return min(hit) if hit else None


def generate_smart_reminders(db: Session, now: datetime | None = None) -> int:
    now = now or utcnow()
    created = 0
    events = db.scalars(
        select(Event).where(Event.status == EventStatus.ACTIVE, Event.starts_at > now, Event.starts_at <= now + timedelta(hours=48))
    ).all()
    for e in events:
        hours_left = (e.starts_at - now).total_seconds() / 3600
        stamp = int(e.starts_at.timestamp())
        base = dict(event_id=e.id, due_at=now)

        # 1) People holding unfinished tasks.
        b = _bucket(hours_left, [24, 3])
        if b:
            rows = db.execute(
                select(TaskAssignment.user_id, TaskAssignment.guest_id, func.count())
                .join(Task, Task.id == TaskAssignment.task_id)
                .where(Task.event_id == e.id, TaskAssignment.completed_at.is_(None))
                .group_by(TaskAssignment.user_id, TaskAssignment.guest_id)
            ).all()
            for user_id, guest_id, n in rows:
                created += _add(
                    db, **base, user_id=user_id, guest_id=guest_id, kind=NotificationKind.TASK_REMINDER,
                    dedupe_key=f"smart_tasks:{e.id}:{actor_key(user_id, guest_id)}:{b}:{stamp}",
                    title=f"{n} task{'s' if n > 1 else ''} to finish for {e.name}",
                    body=f"{e.name} starts in about {round(hours_left)}h. Mark tasks done when you've finished them.",
                )

        # 2) Unclaimed tasks, weighted by overall task completion.
        b = _bucket(hours_left, [24, 6])
        if b:
            counts = dict(db.execute(select(Task.status, func.count()).where(Task.event_id == e.id).group_by(Task.status)).all())
            total = sum(counts.values())
            unclaimed = counts.get(TaskStatus.OPEN, 0)
            if unclaimed:
                done_ratio = counts.get(TaskStatus.COMPLETED, 0) / total
                urgent = done_ratio < 0.5 and hours_left <= 6
                for user_id, guest_id in db.execute(select(RSVP.user_id, RSVP.guest_id).where(RSVP.event_id == e.id)).all():
                    created += _add(
                        db, **base, user_id=user_id, guest_id=guest_id, kind=NotificationKind.SMART_REMINDER,
                        dedupe_key=f"smart_unclaimed:{e.id}:{actor_key(user_id, guest_id)}:{b}:{stamp}",
                        title=("Urgent: " if urgent else "") + f"{unclaimed} task{'s' if unclaimed > 1 else ''} still need someone",
                        body=f"{e.name} starts in about {round(hours_left)}h and {round(done_ratio * 100)}% of tasks are done.",
                    )

        # 3) Minimum participants not reached: nudge group members who have not joined.
        b = _bucket(hours_left, [48, 12])
        if b and e.participant_count < e.min_participants:
            missing = e.min_participants - e.participant_count
            joined = {(u, g) for u, g in db.execute(select(RSVP.user_id, RSVP.guest_id).where(RSVP.event_id == e.id))}
            members = db.execute(
                select(GroupMembership.user_id, GroupMembership.guest_id)
                .join(EventGroup, EventGroup.group_id == GroupMembership.group_id)
                .where(EventGroup.event_id == e.id)
                .distinct()
            ).all()
            for user_id, guest_id in members:
                if (user_id, guest_id) in joined:
                    continue
                created += _add(
                    db, **base, user_id=user_id, guest_id=guest_id, kind=NotificationKind.SMART_REMINDER,
                    dedupe_key=f"smart_min:{e.id}:{actor_key(user_id, guest_id)}:{b}:{stamp}",
                    title=f"{e.name} needs {missing} more {'person' if missing == 1 else 'people'}",
                    body=f"It starts in about {round(hours_left)}h. Join if you can make it!",
                )
    db.commit()
    return created


def run_due_reminders(db: Session, now: datetime | None = None) -> int:
    """Turn due reminders into notifications (preferences are applied by ``notify``)."""
    now = now or utcnow()
    due = db.scalars(
        select(Reminder)
        .join(Event, Event.id == Reminder.event_id)
        .where(Reminder.sent_at.is_(None), Reminder.cancelled_at.is_(None), Reminder.due_at <= now)
        .where(Event.status == EventStatus.ACTIVE, Event.starts_at > now)
        .order_by(Reminder.due_at)
        .limit(1000)
    ).all()
    for r in due:
        # Claim the reminder atomically so overlapping scheduler runs never double-send.
        if db.execute(update(Reminder).where(Reminder.id == r.id, Reminder.sent_at.is_(None)).values(sent_at=now)).rowcount:
            notify(db, [(r.user_id, r.guest_id)], r.kind, r.title, r.body, data={"event_id": r.event_id}, event_id=r.event_id)
    # Reminders for events that started or were cancelled will never be sent.
    db.execute(
        update(Reminder)
        .where(Reminder.sent_at.is_(None), Reminder.cancelled_at.is_(None))
        .where(Reminder.event_id.in_(select(Event.id).where((Event.status != EventStatus.ACTIVE) | (Event.starts_at <= now))))
        .values(cancelled_at=now)
    )
    db.commit()
    return len(due)
